1	import Foundation
2	
3	enum ThreadCardTableResyncReason: String, Equatable, Sendable {
4	    case schemaMismatch
5	    case streamContract
6	    case epochMismatch
7	    case sequenceGap
8	    case staleGeneration
9	}
10	
11	enum ThreadCardTableApplyResult: Equatable, Sendable {
12	    case applied
13	    case needsResync(ThreadCardTableResyncReason)
14	}
15	
16	struct ThreadCardTable: Equatable, Sendable {
17	    private enum ProjectionEnvelope {
18	        static let schemaVersion = 1
19	        static let identityVersion = 1
20	        static let engineVersion = 1
21	        static let rowRole = "threadCard"
22	        static let scope = "view"
23	        static let order = "displayOrderKeyAscending"
24	    }
25	
26	    private struct HostStreamState: Equatable, Sendable {
27	        var epoch: String?
28	        var seq: Int64
29	        var sourceHostID: String?
30	        var status: DockHostLoadStatus
31	        var freshness: DockStreamFreshnessDTO?
32	        var complete: Bool
33	        var totalRows: Int?
34	        var window: DockStreamWindowDTO?
35	        var cardsByID: [String: DockThreadCardDTO]
36	
37	        init(status: DockHostLoadStatus = .checking) {
38	            self.epoch = nil
39	            self.seq = 0
40	            self.status = status
41	            self.freshness = nil
42	            self.complete = false
43	            self.totalRows = nil
44	            self.window = nil
45	            self.cardsByID = [:]
46	        }
47	    }
48	
49	    private let expectedView: ThreadCardStreamView
50	    private var statesByHostID: [String: HostStreamState] = [:]
51	
52	    init(expectedView: ThreadCardStreamView = .dock) {
53	        self.expectedView = expectedView
54	    }
55	
56	    mutating func reset(hosts: [DockHostConfiguration]) {
57	        statesByHostID = Dictionary(
58	            uniqueKeysWithValues: hosts.map { host in
59	                (host.id, HostStreamState())
60	            }
61	        )
62	    }
63	
64	    mutating func ensureHosts(_ hosts: [DockHostConfiguration]) {
65	        let validHostIDs = Set(hosts.map(\.id))
66	        statesByHostID = statesByHostID.filter { validHostIDs.contains($0.key) }
67	        for host in hosts where statesByHostID[host.id] == nil {
68	            statesByHostID[host.id] = HostStreamState()
69	        }
70	    }
71	
72	    mutating func markChecking(host: DockHostConfiguration) {
73	        var state = statesByHostID[host.id] ?? HostStreamState()
74	        let rowCount = state.cardsByID.count
75	        state.status = rowCount > 0
76	            ? .degraded(rowCount: rowCount, message: "Reconnecting")
77	            : .checking
78	        statesByHostID[host.id] = state
79	    }
80	
81	    mutating func markFailure(_ failure: DockRequestFailure, host: DockHostConfiguration) {
82	        var state = statesByHostID[host.id] ?? HostStreamState()
83	        let message = failure.localizedDescription
84	        let rowCount = state.cardsByID.count
85	        switch failure {
86	        case .offline:
87	            state.status = rowCount > 0 ? .degraded(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
88	            state.freshness = DockStreamFreshnessDTO(status: .offline, lastError: message)
89	        case .error:
90	            state.status = rowCount > 0 ? .degraded(rowCount: rowCount, message: message) : .error(message)
91	            state.freshness = DockStreamFreshnessDTO(status: .error, lastError: message)
92	        }
93	        statesByHostID[host.id] = state
94	    }
95	
96	    mutating func applySnapshot(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
97	        guard acceptsSchemaVersion(update.schemaVersion) else {
98	            return .needsResync(.schemaMismatch)
99	        }
100	        guard acceptsStreamContract(update) else {
101	            return .needsResync(.streamContract)
102	        }
103	
104	        var state = statesByHostID[host.id] ?? HostStreamState()
105	        if state.epoch == nil || state.epoch == update.epoch {
106	        }
107	        state.epoch = update.epoch
108	        state.seq = update.seq
109	        state.sourceHostID = update.sourceHostID
110	        state.freshness = update.freshness
111	        state.complete = update.complete ?? false
112	        state.totalRows = update.totalRows
113	        state.window = update.window
114	        state.cardsByID = Dictionary(
115	            uniqueKeysWithValues: (update.rows ?? [])
116	                .filter(\.isAppFacingHumanThreadCard)
117	                .map { card in
118	                    (card.projectionStorageKey, card)
119	                }
120	        )
121	        state.status = hostStatus(
122	            freshness: update.freshness,
123	            rowCount: state.cardsByID.count,
124	            complete: state.complete,
125	            totalRows: state.totalRows,
126	            window: state.window
127	        )
128	        statesByHostID[host.id] = state
129	        return .applied
130	    }
131	
132	    mutating func applyUpdate(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
133	        guard update.kind != .snapshot else {
134	            return applySnapshot(update, host: host)
135	        }
136	
137	        guard acceptsSchemaVersion(update.schemaVersion) else {
138	            return .needsResync(.schemaMismatch)
139	        }
140	        guard var state = statesByHostID[host.id],
141	              state.epoch == update.epoch else {
142	            return .needsResync(.epochMismatch)
143	        }
144	        guard acceptsStreamContract(update, expectedSourceHostID: state.sourceHostID) else {
145	            return .needsResync(.streamContract)
146	        }
147	        guard acceptsProjectionSourceContinuity(update.rows ?? [], existingCardsByID: state.cardsByID) else {
148	            return .needsResync(.streamContract)
149	        }
150	        switch update.kind {
151	        case .heartbeat:
152	            guard state.seq == update.seq else {
153	                return .needsResync(.sequenceGap)
154	            }
155	        case .upsert, .delete:
156	            guard update.seq == state.seq + 1 else {
157	                return .needsResync(.sequenceGap)
158	            }
159	            for projectionID in update.projectionIDs ?? [] {
160	                state.cardsByID.removeValue(forKey: projectionID)
161	            }
162	            for card in (update.rows ?? []).filter(\.isAppFacingHumanThreadCard) {
163	                state.cardsByID[card.projectionStorageKey] = card
164	            }
165	            state.seq = update.seq
166	        case .resyncRequired:
167	            return .needsResync(.streamContract)
168	        case .snapshot:
169	            break
170	        }
171	
172	        state.freshness = update.freshness
173	        state.complete = update.complete ?? state.complete
174	        state.totalRows = update.totalRows ?? state.totalRows
175	        state.window = update.window ?? state.window
176	        state.status = hostStatus(
177	            freshness: state.freshness,
178	            rowCount: state.cardsByID.count,
179	            complete: state.complete,
180	            totalRows: state.totalRows,
181	            window: state.window
182	        )
183	        statesByHostID[host.id] = state
184	        return .applied
185	    }
186	
187	    private func acceptsSchemaVersion(_ schemaVersion: Int) -> Bool {
188	        return schemaVersion == CodexDockConstants.Dock.streamSchemaVersion
189	    }
190	
191	    private func acceptsStreamContract(
192	        _ update: ThreadCardStreamUpdateDTO,
193	        expectedSourceHostID: String? = nil
194	    ) -> Bool {
195	        guard let sourceHostID = nonEmpty(update.sourceHostID),
196	              update.identityVersion == ProjectionEnvelope.identityVersion,
197	              update.projectionEngineVersion == ProjectionEnvelope.engineVersion,
198	              update.scope == ProjectionEnvelope.scope,
199	              nonEmpty(update.viewParamsKey) != nil,
200	              update.order == ProjectionEnvelope.order else {
201	            return false
202	        }
203	        if let expectedSourceHostID,
204	           expectedSourceHostID != sourceHostID {
205	            return false
206	        }
207	        guard update.view == expectedView else {
208	            return false
209	        }
210	        switch update.kind {
211	        case .snapshot:
212	            guard let complete = update.complete,
213	                  let totalRows = update.totalRows,
214	                  let window = update.window else {
215	                return false
216	            }
217	            return acceptsWindowContract(
218	                complete: complete,
219	                totalRows: totalRows,
220	                window: window,
221	                    cardCount: update.rows?.count ?? 0
222	            )
223	                && acceptsProjectionEnvelope(update.rows ?? [], sourceHostID: sourceHostID)
224	        case .upsert, .delete, .heartbeat, .resyncRequired:
225	            guard acceptsProjectionEnvelope(update.rows ?? [], sourceHostID: sourceHostID),
226	                  acceptsDeleteIDs(update.projectionIDs ?? []) else {
227	                return false
228	            }
229	            if update.complete == false {
230	                guard let totalRows = update.totalRows,
231	                      let window = update.window else {
232	                    return false
233	                }
234	                return acceptsWindowContract(
235	                    complete: false,
236	                    totalRows: totalRows,
237	                    window: window,
238	                    cardCount: update.rows?.count ?? 0
239	                )
