245	    private func acceptsWindowContract(
246	        complete: Bool,
247	        totalRows: Int,
248	        window: DockStreamWindowDTO,
249	        cardCount: Int
250	    ) -> Bool {
251	        guard totalRows >= 0,
252	              window.offset >= 0,
253	              window.limit >= 0,
254	              window.rowCount >= 0,
255	              window.rowCount == cardCount else {
256	            return false
257	        }
258	        if let nextOffset = window.nextOffset,
259	           nextOffset <= window.offset {
260	            return false
261	        }
262	        return complete || window.rowCount <= totalRows
263	    }
