265	    private func acceptsProjectionEnvelope(_ cards: [DockThreadCardDTO], sourceHostID expectedSourceHostID: String) -> Bool {
266	        var seenProjectionIDs = Set<String>()
267	        var seenSourceKeys = Set<ThreadCardProjectionSourceKey>()
268	        for card in cards {
269	            guard let sourceHostID = nonEmpty(card.sourceHostID) else {
270	                return false
271	            }
272	            guard card.schemaVersion == ProjectionEnvelope.schemaVersion
273	                && card.identityVersion == ProjectionEnvelope.identityVersion
274	                && card.projectionEngineVersion == ProjectionEnvelope.engineVersion
275	                && sourceHostID == expectedSourceHostID
276	                && card.logicalHostID == sourceHostID
277	                && card.view == expectedView.rawValue
278	                && nonEmpty(card.projectionID) != nil
279	                && card.id == card.projectionID
280	                && nonEmpty(card.sourceRef) != nil
281	                && card.rowRole == ProjectionEnvelope.rowRole
282	                && nonEmpty(card.displayOrderKey) != nil else {
283	                return false
284	            }
285	            guard seenProjectionIDs.insert(card.projectionID).inserted else {
286	                return false
287	            }
288	            guard seenSourceKeys.insert(ThreadCardProjectionSourceKey(card)).inserted else {
289	                return false
290	            }
291	        }
292	        return true
293	    }
