295	    private func acceptsProjectionSourceContinuity(
296	        _ cards: [DockThreadCardDTO],
297	        existingCardsByID: [String: DockThreadCardDTO]
298	    ) -> Bool {
299	        var existingProjectionIDsBySourceKey = [ThreadCardProjectionSourceKey: String]()
300	        for card in existingCardsByID.values {
301	            let sourceKey = ThreadCardProjectionSourceKey(card)
302	            if existingProjectionIDsBySourceKey.updateValue(card.projectionStorageKey, forKey: sourceKey) != nil {
303	                return false
304	            }
305	        }
306	        for card in cards {
307	            let sourceKey = ThreadCardProjectionSourceKey(card)
308	            if let existing = existingCardsByID[card.projectionStorageKey],
309	               ThreadCardProjectionSourceKey(existing) != sourceKey {
310	                return false
311	            }
312	            if let existingProjectionID = existingProjectionIDsBySourceKey[sourceKey],
313	               existingProjectionID != card.projectionStorageKey {
314	                return false
315	            }
316	        }
317	        return true
318	    }
