343	    func renderInput(hosts: [DockHostConfiguration]) -> DockRenderInput {
344	        let hostStates = hosts.map { host in
345	            DockHostStateViewModel(
346	                host: DockHostViewModel(host: host),
347	                status: statesByHostID[host.id]?.status ?? .checking
348	            )
349	        }
350	        let statuses = Dictionary(
351	            uniqueKeysWithValues: hostStates.map { ($0.host.id, $0.status) }
352	        )
353	        return DockRenderInput(
354	            hosts: hosts,
355	            hostStates: hostStates,
356	            hostIdentityResolver: DockHostIdentityResolver(
357	                hosts: hosts,
358	                observations: identityObservations(hosts: hosts),
359	                hostStatuses: statuses
360	            ),
361	            cardsByHostID: Dictionary(
362	                uniqueKeysWithValues: hosts.map { host in
363	                    (host.id, sortedCards(for: host))
364	                }
365	            ),
366	            isPartial: hosts.contains(where: needsProgressContext)
367	        )
368	    }
