159	        shouldStop: @MainActor () -> Bool = { false },
160	        onProgress: @MainActor ([ArchiveRestoreResult]) -> Void = { _ in }
161	    ) async -> [ArchiveRestoreResult] {
162	        guard !rows.isEmpty else {
163	            return []
164	        }
165	
166	        var didRestoreAnyRow = false
167	        var results: [ArchiveRestoreResult] = []
168	        for row in rows {
169	            if shouldStop() {
170	                results.append(ArchiveRestoreResult(row: row, status: .skipped))
171	                onProgress(results)
172	                continue
173	            }
174	
175	            let result = await restoreRow(row)
176	            if case .restored = result.status {
177	                didRestoreAnyRow = true
178	            }
179	            results.append(result)
180	            onProgress(results)
181	        }
