189	    private func restoreRow(_ row: DockRowViewModel) async -> ArchiveRestoreResult {
190	        guard let host = hostConfiguration(for: row) else {
191	            DockLog.archive.error("archive restore skipped missing host_id=\(row.hostID, privacy: .public) thread_id=\(DockLog.publicID(row.threadID), privacy: .public)")
192	            let message = "Host \(row.hostID) is no longer configured."
193	            setActionError(message)
194	            return ArchiveRestoreResult(row: row, status: .failed(message))
195	        }
196	
197	        do {
198	            DockLog.archive.notice("archive restore action started host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.threadID), privacy: .public)")
199	            try await commandEngine.unarchive(row, on: host)
200	            setActionError(nil)
201	            DockLog.archive.notice("archive restore action finished host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.threadID), privacy: .public)")
202	            return ArchiveRestoreResult(row: row, status: .restored)
203	        } catch {
204	            DockLog.archive.error("archive restore action failed host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
