242	    private func reload(showLoading: Bool) async {
243	        guard !hosts.isEmpty else {
244	            DockLog.archive.warning("archive reload skipped reason=no_hosts")
245	            return
246	        }
247	        guard !isLoading else {
248	            DockLog.archive.debug("archive reload skipped reason=already_loading")
249	            return
250	        }
251	
252	        let startedAt = Date()
253	        let signpostState = DockSignpost.archive.beginInterval("archive.reload")
254	        DockLog.archive.notice("archive reload started hosts=\(self.hosts.count, privacy: .public) show_loading=\(showLoading, privacy: .public)")
255	        isLoading = true
256	        defer {
257	            DockSignpost.archive.endInterval("archive.reload", signpostState)
258	            isLoading = false
259	        }
260	
261	        if showLoading {
262	            setState(.loading(hosts.map(DockHostViewModel.init)))
263	            publishConnectivity(for: state)
264	        }
265	
266	        guard let dataEngine else {
267	            DockLog.archive.warning("archive reload skipped reason=no_data_engine")
268	            return
269	        }
270	
271	        await dataEngine.loadLocalMetadata()
272	        await dataEngine.ensureHosts()
273	        await streamLifecycle?.synchronizeStreams(hosts: hosts)
274	        await dataEngine.migrateMetadataHostAliases()
275	        await publishSnapshot()
276	        if let snapshot = await dataEngine.snapshot() {
277	            DockLog.archive.notice("archive stream reload finished hosts=\(self.hosts.count, privacy: .public) rows=\(snapshot.rowCount, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
278	        }
279	    }
