311	        guard let connectivityEventSink else {
312	            return
313	        }
314	        let events = connectivityEvents(for: state)
315	        guard !events.isEmpty else {
316	            return
317	        }
318	        Task {
319	            for event in events {
320	                await connectivityEventSink.record(event)
321	            }
322	        }
323	    }
