325	    private func connectivityEvents(for state: ArchiveStoreState) -> [ConnectivityRuntimeEvent] {
326	        switch state {
327	        case .configurationError(let message):
328	            return [
329	                ConnectivityRuntimeEvent(
330	                    source: .archive,
331	                    hostID: nil,
332	                    route: "archive/configuration",
333	                    status: message,
334	                    phase: .configurationError(message)
335	                )
336	            ]
337	        case .idle(let hosts):
338	            return hosts.map { host in
339	                ConnectivityRuntimeEvent(
340	                    source: .archive,
341	                    hostID: host.id,
342	                    route: "archive",
343	                    status: "idle",
344	                    phase: .unknown
345	                )
346	            }
347	        case .loading(let hosts):
348	            return hosts.map { host in
349	                ConnectivityRuntimeEvent(
350	                    source: .archive,
351	                    hostID: host.id,
352	                    route: "archive/subscribe",
353	                    status: "checking",
354	                    phase: .checking
355	                )
356	            }
357	        case .loaded(let snapshot), .empty(let snapshot), .unavailable(let snapshot, _):
358	            return snapshot.hostStates.map { hostState in
359	                ConnectivityRuntimeEvent(
360	                    source: .archive,
361	                    hostID: hostState.host.id,
362	                    route: "archive/subscribe",
363	                    status: hostState.status.subtitle,
364	                    phase: Self.connectivityPhase(for: hostState.status)
365	                )
366	            }
367	        }
368	    }
