370	    private nonisolated static func connectivityPhase(
371	        for status: DockHostLoadStatus
372	    ) -> HostConnectivityPhase {
373	        switch status {
374	        case .checking:
375	            return .checking
376	        case .loaded(let rowCount, _):
377	            return .online("\(rowCount) sessions")
378	        case .degraded(_, let message):
379	            return .partial(message)
380	        case .empty:
381	            return .online("Online, no sessions")
382	        case .offline(let message):
383	            return .offline(message)
384	        case .error(let message):
385	            return .error(message)
386	        }
387	    }
388	}
