106	struct DockPinnedSectionView<RowContent: View>: View {
107	    let projection: DockCardProjection
108	    @Binding var isCollapsed: Bool
109	    let onMove: ([DockRowViewModel]) -> Void
110	    let onUnpin: (DockRowViewModel) -> Void
111	    let onOpen: (DockRowViewModel) -> Void
112	    @ViewBuilder let rowContent: (DockRowViewModel) -> RowContent
113	    @State private var isReorderPresented = false
114	
115	    var body: some View {
116	        VStack(alignment: .leading, spacing: 8) {
117	            HStack(spacing: 8) {
118	                Button {
119	                    withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
120	                        isCollapsed.toggle()
121	                    }
122	                } label: {
123	                    HStack(spacing: 8) {
124	                        Label(headerTitle, systemImage: "pin.fill")
125	                            .font(.subheadline.weight(.semibold))
126	                            .foregroundStyle(.primary)
127	                            .accessibilityAddTraits(.isHeader)
128	                            .codexAutomationID(AutomationID.Dock.pinnedHeader)
129	
130	                        Image(systemName: isCollapsed ? "chevron.right" : "chevron.down")
131	                            .font(.caption.weight(.bold))
132	                            .foregroundStyle(.secondary)
133	                            .accessibilityHidden(true)
134	                    }
135	                }
136	                .buttonStyle(.plain)
137	                .accessibilityLabel("Pinned")
138	                .accessibilityValue(isCollapsed ? "Collapsed, \(headerTitle)" : "Expanded, \(headerTitle)")
139	                .codexAutomationID(AutomationID.Dock.pinnedToggleButton)
140	
141	                Spacer(minLength: 8)
142	
143	                if projection.pinnedRows.count > 1 {
144	                    Button {
145	                        isReorderPresented = true
146	                    } label: {
147	                        Label("Reorder", systemImage: "arrow.up.arrow.down")
148	                            .labelStyle(.iconOnly)
149	                    }
150	                    .buttonStyle(.bordered)
151	                    .accessibilityLabel("Reorder pinned rows")
152	                    .codexAutomationID(AutomationID.Dock.pinnedReorderButton)
153	                }
154	            }
155	
156	            if !isCollapsed {
157	                DockPinnedRowsList(
158	                    rows: projection.pinnedRows,
159	                    onUnpin: onUnpin,
160	                    onOpen: onOpen,
161	                    rowContent: rowContent
