163	            }
164	        }
165	        .sheet(isPresented: $isReorderPresented) {
166	            DockPinnedReorderView(
167	                rows: projection.pinnedRows,
168	                onCancel: { isReorderPresented = false },
169	                onSave: { rows in
170	                    isReorderPresented = false
171	                    onMove(rows)
172	                },
173	                rowContent: rowContent
174	            )
175	        }
176	        .accessibilityElement(children: .contain)
177	        .accessibilityValue(headerTitle)
178	        .codexAutomationID(AutomationID.Dock.pinnedSection)
179	    }
180	
181	    private var headerTitle: String {
182	        projection.pinnedSummary.totalCount > projection.pinnedSummary.visibleCount
183	            ? "Pinned \(projection.pinnedSummary.visibleCount) of \(projection.pinnedSummary.totalCount)"
184	            : "Pinned \(projection.pinnedSummary.visibleCount)"
185	    }
186	}
