220	struct DockPinnedRowsList<RowContent: View>: View {
221	    let rows: [DockRowViewModel]
222	    let onUnpin: (DockRowViewModel) -> Void
223	    let onOpen: (DockRowViewModel) -> Void
224	    @ViewBuilder let rowContent: (DockRowViewModel) -> RowContent
