235	                        threadID: row.threadID,
236	                        action: .unpin
237	                    ),
238	                    onTogglePinned: {
239	                        onUnpin(row)
240	                    },
241	                    canOpen: true,
242	                    onOpen: {
243	                        onOpen(row)
244	                    }
245	                ) {
246	                    rowContent(row)
247	                }
248	            }
249	        }
250	        .codexAutomationID(AutomationID.Dock.pinnedRowsList)
251	    }
252	}
