254	private struct DockPinnedReorderView<RowContent: View>: View {
255	    @State private var rows: [DockRowViewModel]
256	    let onCancel: () -> Void
257	    let onSave: ([DockRowViewModel]) -> Void
258	    @ViewBuilder let rowContent: (DockRowViewModel) -> RowContent
259	
260	    init(
261	        rows: [DockRowViewModel],
262	        onCancel: @escaping () -> Void,
263	        onSave: @escaping ([DockRowViewModel]) -> Void,
264	        @ViewBuilder rowContent: @escaping (DockRowViewModel) -> RowContent
265	    ) {
266	        _rows = State(initialValue: rows)
267	        self.onCancel = onCancel
268	        self.onSave = onSave
269	        self.rowContent = rowContent
270	    }
271	
272	    var body: some View {
273	        NavigationStack {
274	            reorderList
275	            .navigationTitle("Reorder pinned")
276	            .toolbar {
277	                ToolbarItem(placement: .cancellationAction) {
278	                    Button("Cancel", action: onCancel)
279	                }
280	                ToolbarItem(placement: .confirmationAction) {
281	                    Button("Done") {
282	                        onSave(rows)
283	                    }
284	                }
285	            }
286	        }
287	        .codexAutomationID(AutomationID.Dock.pinnedReorderSheet)
288	    }
289	
290	    @ViewBuilder
291	    private var reorderList: some View {
292	        let list = List {
293	            ForEach(rows) { row in
294	                rowContent(row)
295	            }
296	            .onMove { source, destination in
297	                rows.move(fromOffsets: source, toOffset: destination)
298	            }
299	        }
300	        #if os(iOS)
301	        list.environment(\.editMode, .constant(.active))
302	        #else
303	        list
304	        #endif
305	    }
306	}
