1	import Foundation
2	import OSLog
3	
4	@MainActor
5	protocol ThreadCardStreamLifecycleDelegate: AnyObject {
6	    func cardStreamLifecycleMarkChecking(host: DockHostConfiguration) async
7	    func cardStreamLifecycleMarkFailure(_ failure: DockRequestFailure, host: DockHostConfiguration) async
8	    func cardStreamLifecycleApplySnapshot(
9	        _ update: ThreadCardStreamUpdateDTO,
10	        host: DockHostConfiguration
11	    ) async -> ThreadCardTableApplyResult
12	    func cardStreamLifecycleApplyUpdate(
13	        _ update: ThreadCardStreamUpdateDTO,
14	        host: DockHostConfiguration
15	    ) async -> ThreadCardTableApplyResult
16	    func cardStreamLifecycleRowCount(for host: DockHostConfiguration) async -> Int
17	    func cardStreamLifecyclePublishSnapshot() async
18	    func cardStreamLifecycleMigrateMetadataHostAliases() async
19	}
20	
21	@MainActor
22	final class ThreadCardStreamLifecycle {
23	    private let view: ThreadCardStreamView
24	    private let streamClient: any ThreadCardStreamConnecting
25	    private let streamReconnectDelay: Duration
26	    private let streamHeartbeatTimeout: Duration
27	    private let logger: Logger
28	    private let logName: String
29	    private weak var delegate: (any ThreadCardStreamLifecycleDelegate)?
30	
31	    private var streamConnections: [String: any ThreadCardStreamConnection] = [:]
32	    private var streamTasks: [String: Task<Void, Never>] = [:]
33	    private var streamHeartbeatTasks: [String: Task<Void, Never>] = [:]
34	    private var streamHeartbeatTokens: [String: UUID] = [:]
35	
36	    init(
37	        view: ThreadCardStreamView,
38	        streamClient: any ThreadCardStreamConnecting,
39	        streamReconnectDelay: Duration,
40	        streamHeartbeatTimeout: Duration,
41	        logger: Logger,
42	        logName: String,
43	        delegate: any ThreadCardStreamLifecycleDelegate
44	    ) {
45	        self.view = view
46	        self.streamClient = streamClient
47	        self.streamReconnectDelay = streamReconnectDelay
48	        self.streamHeartbeatTimeout = streamHeartbeatTimeout
49	        self.logger = logger
50	        self.logName = logName
51	        self.delegate = delegate
52	    }
53	
54	    deinit {
55	        streamTasks.values.forEach { $0.cancel() }
56	        streamHeartbeatTasks.values.forEach { $0.cancel() }
57	    }
58	
59	    func synchronizeStreams(hosts: [DockHostConfiguration]) async {
60	        let validHostIDs = Set(hosts.map(\.id))
61	        for hostID in streamConnections.keys where !validHostIDs.contains(hostID) {
62	            streamTasks[hostID]?.cancel()
63	            streamTasks[hostID] = nil
64	            streamHeartbeatTasks[hostID]?.cancel()
65	            streamHeartbeatTasks[hostID] = nil
66	            streamHeartbeatTokens[hostID] = nil
67	            let connection = streamConnections.removeValue(forKey: hostID)
68	            await connection?.close()
69	        }
70	
71	        for host in hosts {
72	            if let connection = streamConnections[host.id] {
73	                await resync(host: host, connection: connection)
74	            } else {
75	                await openStream(host: host)
76	            }
77	        }
78	    }
79	
80	    func closeStreams() async {
81	        streamTasks.values.forEach { $0.cancel() }
82	        streamTasks = [:]
83	        streamHeartbeatTasks.values.forEach { $0.cancel() }
84	        streamHeartbeatTasks = [:]
85	        streamHeartbeatTokens = [:]
86	        let connections = streamConnections
87	        streamConnections = [:]
88	        for connection in connections.values {
89	            await connection.close()
90	        }
91	    }
92	
93	    private func openStream(host: DockHostConfiguration) async {
94	        guard let delegate else {
95	            return
96	        }
97	
98	        await delegate.cardStreamLifecycleMarkChecking(host: host)
99	        await delegate.cardStreamLifecyclePublishSnapshot()
100	        var openedConnection: (any ThreadCardStreamConnection)?
101	        do {
102	            let connection = try await streamClient.connect(to: host)
103	            openedConnection = connection
104	            streamConnections[host.id] = connection
105	            let snapshot = try await connection.subscribe()
106	            try await applySubscribedSnapshot(snapshot, host: host, connection: connection)
107	            recordStreamActivity(host: host, connection: connection)
108	            startUpdateTask(host: host, connection: connection)
109	            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
110	            await delegate.cardStreamLifecyclePublishSnapshot()
111	        } catch {
112	            streamTasks[host.id]?.cancel()
113	            streamTasks[host.id] = nil
114	            streamHeartbeatTasks[host.id]?.cancel()
115	            streamHeartbeatTasks[host.id] = nil
116	            streamHeartbeatTokens[host.id] = nil
117	            streamConnections[host.id] = nil
118	            await openedConnection?.close()
119	            logger.warning("\(self.logName, privacy: .public) stream open failed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
120	            await delegate.cardStreamLifecycleMarkFailure(Self.mapRequestFailure(error), host: host)
121	            await delegate.cardStreamLifecyclePublishSnapshot()
122	        }
123	    }
124	
125	    private func resync(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) async {
126	        guard let delegate else {
127	            return
128	        }
129	
130	        do {
131	            let snapshot = try await connection.resync()
132	            try await applyResyncSnapshot(snapshot, host: host)
133	            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
134	            await delegate.cardStreamLifecyclePublishSnapshot()
135	            let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
136	            logger.notice("\(self.logName, privacy: .public) stream resync finished view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) seq=\(snapshot.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
137	        } catch {
138	            logger.warning("\(self.logName, privacy: .public) stream resync failed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
139	            await delegate.cardStreamLifecycleMarkFailure(Self.mapRequestFailure(error), host: host)
140	            await delegate.cardStreamLifecyclePublishSnapshot()
141	        }
142	    }
143	
144	    private func startUpdateTask(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) {
145	        streamTasks[host.id]?.cancel()
146	        streamTasks[host.id] = Task { [weak self, host, connection] in
147	            do {
148	                for try await update in connection.updates() {
149	                    await self?.handleStreamUpdate(update, host: host, connection: connection)
150	                }
151	                if !Task.isCancelled {
152	                    await self?.handleStreamFailure(
153	                        DockRequestFailure.offline("Relay stream closed"),
154	                        host: host,
155	                        connection: connection
156	                    )
157	                }
158	            } catch is CancellationError {
159	                return
160	            } catch {
161	                await self?.handleStreamFailure(error, host: host, connection: connection)
162	            }
163	        }
164	    }
165	
166	    private func recordStreamActivity(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) {
167	        let token = UUID()
168	        streamHeartbeatTokens[host.id] = token
169	        streamHeartbeatTasks[host.id]?.cancel()
170	        streamHeartbeatTasks[host.id] = Task { [weak self, host, connection, token] in
171	            guard let self else {
172	                return
173	            }
174	            let timeout = streamHeartbeatTimeout
175	            do {
176	                try await Task.sleep(for: timeout)
177	            } catch {
178	                return
179	            }
180	            await self.handleHeartbeatTimeout(host: host, connection: connection, token: token)
181	        }
182	    }
183	
184	    private func handleHeartbeatTimeout(
185	        host: DockHostConfiguration,
186	        connection: any ThreadCardStreamConnection,
187	        token: UUID
188	    ) async {
189	        guard streamHeartbeatTokens[host.id] == token else {
190	            return
191	        }
192	        logger.warning("\(self.logName, privacy: .public) stream heartbeat timed out view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public)")
193	        await handleStreamFailure(
194	            DockRequestFailure.offline("Relay stream heartbeat timed out"),
195	            host: host,
196	            connection: connection
197	        )
198	    }
199	
200	    private func handleStreamUpdate(
201	        _ update: ThreadCardStreamUpdateDTO,
202	        host: DockHostConfiguration,
203	        connection: any ThreadCardStreamConnection
204	    ) async {
205	        guard let delegate else {
206	            return
207	        }
208	
209	        recordStreamActivity(host: host, connection: connection)
210	        let result = await delegate.cardStreamLifecycleApplyUpdate(update, host: host)
211	        if case .needsResync(let reason) = result {
212	            logger.warning("\(self.logName, privacy: .public) stream resync needed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public)")
213	            await resync(host: host, connection: connection)
214	        } else {
215	            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
216	            await delegate.cardStreamLifecyclePublishSnapshot()
217	            let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
218	            logger.info("\(self.logName, privacy: .public) stream update applied view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
219	            let freshness = update.freshness
220	            if freshness.status != .fresh,
221	               rowCount > 0 {
222	                logger.notice("\(self.logName, privacy: .public) stream rows retained view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) freshness=\(freshness.status.rawValue, privacy: .public) rows=\(rowCount, privacy: .public)")
223	            }
224	        }
225	    }
226	
227	    private func applySubscribedSnapshot(
228	        _ snapshot: ThreadCardStreamUpdateDTO,
229	        host: DockHostConfiguration,
230	        connection: any ThreadCardStreamConnection
231	    ) async throws {
232	        guard let delegate else {
233	            return
234	        }
235	
236	        switch await delegate.cardStreamLifecycleApplySnapshot(snapshot, host: host) {
237	        case .applied:
238	            return
239	        case .needsResync(let reason):
240	            logger.warning("\(self.logName, privacy: .public) stream subscribe snapshot rejected view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) seq=\(snapshot.seq, privacy: .public)")
241	            let resynced = try await connection.resync()
242	            try await applyResyncSnapshot(resynced, host: host)
243	        }
244	    }
245	
246	    private func applyResyncSnapshot(
247	        _ snapshot: ThreadCardStreamUpdateDTO,
248	        host: DockHostConfiguration
249	    ) async throws {
250	        guard let delegate else {
251	            return
252	        }
253	
254	        switch await delegate.cardStreamLifecycleApplySnapshot(snapshot, host: host) {
255	        case .applied:
256	            return
257	        case .needsResync(let reason):
258	            throw DockRequestFailure.error("\(logName.capitalized) stream resync returned incompatible data (\(reason.rawValue)).")
259	        }
260	    }
261	
262	    private func handleStreamFailure(
263	        _ error: Error,
264	        host: DockHostConfiguration,
265	        connection: any ThreadCardStreamConnection
266	    ) async {
267	        guard streamConnections[host.id] != nil else {
268	            return
269	        }
270	        guard let delegate else {
271	            return
272	        }
273	
274	        logger.warning("\(self.logName, privacy: .public) stream update failed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
275	        streamHeartbeatTasks[host.id]?.cancel()
276	        streamHeartbeatTasks[host.id] = nil
277	        streamHeartbeatTokens[host.id] = nil
278	        streamConnections[host.id] = nil
279	        streamTasks[host.id] = nil
280	        await connection.close()
281	        await delegate.cardStreamLifecycleMarkFailure(Self.mapRequestFailure(error), host: host)
282	        await delegate.cardStreamLifecyclePublishSnapshot()
283	        let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
284	        if rowCount > 0 {
285	            logger.notice("\(self.logName, privacy: .public) stream rows retained view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) freshness=offline rows=\(rowCount, privacy: .public)")
286	        }
287	        scheduleReconnect(host: host)
288	    }
289	
290	    private func scheduleReconnect(host: DockHostConfiguration) {
291	        streamTasks[host.id] = Task { [weak self, host] in
292	            do {
293	                try await Task.sleep(for: self?.streamReconnectDelay ?? CodexDockConstants.Dock.autoRefreshInterval)
294	            } catch {
295	                return
296	            }
297	            await self?.openStream(host: host)
298	        }
299	    }
