208	                .font(.caption.weight(.semibold))
209	                .lineLimit(1)
210	                .frame(maxWidth: .infinity)
211	                .padding(.horizontal, 8)
212	                .padding(.vertical, 7)
213	        }
214	        .buttonStyle(.plain)
215	        .foregroundStyle(isSelected ? .white : .primary)
216	        .background(
217	            isSelected ? Color.blue : Color.secondary.opacity(0.12),
218	            in: RoundedRectangle(cornerRadius: 8, style: .continuous)
219	        )
220	        .accessibilityAddTraits(isSelected ? .isSelected : [])
221	        .codexAutomationID(automationID)
222	    }
223	
224	    private func toggle(_ value: String, in set: inout Set<String>) {
225	        if set.contains(value) {
226	            set.remove(value)
227	        } else {
228	            set.insert(value)
229	        }
230	    }
231	
232	    private func toggleStatus(_ status: DockRowStatusKind) {
233	        if filters.statusKinds == Set(DockRowStatusKind.allCases) {
234	            filters.statusKinds = [status]
235	            return
236	        }
237	        if filters.statusKinds.contains(status) {
238	            filters.statusKinds.remove(status)
239	            if filters.statusKinds.isEmpty {
240	                filters.statusKinds = Set(DockRowStatusKind.allCases)
241	            }
242	        } else {
243	            filters.statusKinds.insert(status)
244	        }
245	    }
246	
247	    private func orderedUnique<Value: Hashable>(_ values: [Value]) -> [Value] {
248	        var seen: Set<Value> = []
249	        return values.filter { seen.insert($0).inserted }
250	    }
251	}
