38	    init(configurationError message: String) {
39	        self.state = .configurationError(message)
40	        self.options = DockProjectionOptions()
41	        self.searchText = ""
42	        self.coalescer = RenderCoalescer<DockRenderSnapshot>()
43	        self.now = Date.init
44	        self.actionError = nil
45	    }
46	
47	    deinit {
48	        renderTask?.cancel()
49	        searchDebounceTask?.cancel()
50	    }
51	
52	    func start() {
53	        guard renderTask == nil else {
54	            return
55	        }
56	
57	        renderTask = Task { [weak self, coalescer] in
58	            let stream = await coalescer.stream()
59	            for await renderSnapshot in stream {
60	                await MainActor.run {
61	                    self?.state = .loaded(renderSnapshot)
62	                }
63	            }
64	        }
65	    }
66	
67	    func stop() {
68	        renderTask?.cancel()
69	        renderTask = nil
70	        searchDebounceTask?.cancel()
71	        searchDebounceTask = nil
72	    }
73	
74	    func setLoading(hosts: [DockHostViewModel]) {
75	        state = .loading(hosts)
76	    }
77	
78	    func setIdle(hosts: [DockHostViewModel]) {
79	        state = .idle(hosts)
80	    }
