90	    func setLens(_ lens: DockLensID) {
91	        updateOptions(
92	            DockProjectionOptions(
93	                lens: lens,
94	                searchText: searchText,
95	                filters: options.filters
96	            ),
97	            syncSearchText: false
98	        )
99	    }
100	
101	    func setSearchText(_ searchText: String) {
102	        self.searchText = searchText
103	        searchDebounceTask?.cancel()
104	        searchDebounceTask = Task { [weak self] in
105	            do {
106	                try await Task.sleep(
107	                    for: .milliseconds(CodexDockConstants.Rendering.searchDebounceMilliseconds)
108	                )
109	            } catch {
110	                return
111	            }
112	            await MainActor.run {
113	                self?.applySearchText(searchText)
114	            }
115	        }
116	    }
117	
118	    private func applySearchText(_ searchText: String) {
119	        searchDebounceTask = nil
120	        updateOptions(
121	            DockProjectionOptions(
122	                lens: options.lens,
123	                searchText: searchText,
124	                filters: options.filters
125	            )
126	        )
127	    }
128	
129	    func setFilters(_ filters: DockFilterState) {
130	        updateOptions(
131	            DockProjectionOptions(
132	                lens: options.lens,
133	                searchText: searchText,
134	                filters: filters
135	            ),
136	            syncSearchText: false
137	        )
138	    }
139	
140	    func updateOptions(_ options: DockProjectionOptions, syncSearchText: Bool = true) {
141	        self.options = options
142	        if syncSearchText {
143	            searchText = options.searchText
144	        }
145	        guard case .loaded(let renderSnapshot) = state else {
146	            return
147	        }
148	        enqueueProjection(snapshot: renderSnapshot.snapshot)
149	    }
150	
151	    func publish(snapshot: DockSnapshot) {
152	        enqueueProjection(snapshot: snapshot)
153	    }
154	
155	    private func enqueueProjection(snapshot: DockSnapshot) {
156	        latestRevision = latestRevision.next()
157	        let revision = latestRevision
158	        let options = self.options
159	        let now = self.now
160	        let coalescer = self.coalescer
161	        if snapshot.rows.count > CodexDockConstants.Rendering.maxDockRowsPerMainPublish {
162	            DockLog.rendering.warning("dock render input exceeds main publish row budget rows=\(snapshot.rows.count, privacy: .public) budget=\(CodexDockConstants.Rendering.maxDockRowsPerMainPublish, privacy: .public)")
163	        }
164	
165	        Task.detached(priority: .userInitiated) {
166	            let signpostState = DockSignpost.rendering.beginInterval(RenderSignpostName.dockRenderProject)
167	            defer {
168	                DockSignpost.rendering.endInterval(RenderSignpostName.dockRenderProject, signpostState)
169	            }
170	            let renderSnapshot = DockRenderProjector(now: now).render(
171	                snapshot: snapshot,
172	                options: options,
173	                revision: revision
174	            )
175	            await coalescer.submit(renderSnapshot, revision: revision)
176	        }
177	    }
178	}
