488	    viewParamsKey: params.viewParamsKey || envelopes.at(-1)?.viewParamsKey || null,
489	    epoch: params.epoch || envelopes.at(-1)?.epoch || null,
490	    lastSeq,
491	    envelopes,
492	    projectionIDs: projectionIDsFromWitnessEnvelopes(envelopes),
493	  };
494	}
495	
496	function sendThreadDetailUpdate(config, downstreamWs, update) {
497	  if (!update) {
498	    return;
499	  }
500	  recordProjectionWitness(config, update);
501	  sendJson(downstreamWs, {
502	    jsonrpc: "2.0",
503	    method: THREAD_DETAIL_UPDATE_METHOD,
504	    params: update,
505	  });
506	}
507	
508	function handleDetailNotification(config, session, downstreamWs, generation, message) {
509	  const detail = session.detailSubscription;
510	  if (!detail || detail.generation !== generation) {
511	    return false;
512	  }
513	  if (detail.buffering || !detail.ledger) {
514	    detail.pendingMessages.push({ type: "notification", message });
515	    return true;
516	  }
517	  sendThreadDetailUpdate(config, downstreamWs, detail.ledger.applyNotification(message));
518	  return true;
519	}
520	
521	function handleDetailRequest(config, session, downstreamWs, generation, message) {
522	  const detail = session.detailSubscription;
523	  if (!detail || detail.generation !== generation) {
524	    return false;
525	  }
526	  if (detail.buffering || !detail.ledger) {
527	    detail.pendingMessages.push({ type: "request", message });
528	    return true;
529	  }
530	  sendThreadDetailUpdate(config, downstreamWs, detail.ledger.applyRequest(message));
531	  return true;
532	}
533	
534	function replayPendingDetailMessages(session) {
535	  const detail = session.detailSubscription;
536	  if (!detail?.ledger) {
537	    return;
538	  }
539	  const pending = detail.pendingMessages.splice(0);
540	  for (const entry of pending) {
541	    if (entry.type === "notification") {
542	      detail.ledger.applyNotification(entry.message);
543	    } else if (entry.type === "request") {
544	      detail.ledger.applyRequest(entry.message);
545	    }
546	  }
547	}
548	
549	async function readThreadDetail(config, params = {}) {
550	  const ledger = await readThreadDetailLedger(config, params);
551	  const snapshot = ledger.snapshot("thread/detail/read");
552	  recordProjectionWitness(config, snapshot);
553	  return snapshot;
554	}
555	
556	async function subscribeThreadDetail(config, params = {}, session, downstreamWs) {
557	  await resumeThread(config, params, session, downstreamWs, { detailSubscription: true });
558	  const detail = session.detailSubscription;
559	  try {
560	    const ledger = await readThreadDetailLedger(config, params);
561	    detail.ledger = ledger;
562	    replayPendingDetailMessages(session);
563	    detail.buffering = false;
564	    const snapshot = ledger.snapshot("thread/detail/subscribe");
565	    recordProjectionWitness(config, snapshot);
566	    return snapshot;
567	  } catch (error) {
568	    if (session.detailSubscription === detail) {
569	      session.detailSubscription = null;
570	    }
571	    throw error;
572	  }
573	}
574	
575	async function resyncThreadDetail(config, params = {}, session) {
576	  const ledger = await readThreadDetailLedger(config, params);
577	  const detail = session.detailSubscription;
578	  if (detail?.threadId === params.threadId) {
579	    detail.ledger = ledger;
580	    detail.buffering = false;
581	    detail.pendingMessages = [];
582	    for (const pending of session.pendingServerRequests?.values?.() || []) {
583	      if (pending.threadId === params.threadId && pending.message) {
584	        ledger.applyRequest(pending.message);
585	      }
586	    }
587	  }
588	  const snapshot = ledger.snapshot("thread/detail/resync");
589	  recordProjectionWitness(config, snapshot);
590	  return snapshot;
591	}
592	
593	function makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation) {
594	  let client;
595	  client = new JsonRpcWebSocketClient(endpoint.url, {
596	    bearerToken: endpoint.bearerToken || null,
597	    logger: relayLogger(config),
598	    onNotification: (message) => {
599	      if (isSessionActive(session, downstreamWs, generation)) {
600	        if (!handleDetailNotification(config, session, downstreamWs, generation, message)) {
601	          sendJson(downstreamWs, message);
602	        }
603	      }
604	    },
605	    onRequest: (message) => {
606	      if (isSessionActive(session, downstreamWs, generation)) {
607	        session.pendingServerRequests.set(String(message.id), {
608	          generation,
609	          threadId: message?.params?.threadId || session.resumeParams?.threadId || null,
610	          method: message.method,
611	          message,
612	        });
613	        if (!handleDetailRequest(config, session, downstreamWs, generation, message)) {
614	          sendJson(downstreamWs, message);
615	        }
616	      }
617	    },
618	    onClose: () => {
619	      handleSessionUpstreamClose(config, session, downstreamWs, client);
620	    },
621	  });
622	  return client;
623	}
624	
625	function handleSessionUpstreamClose(config, session, downstreamWs, closedClient) {
626	  if (session.closing || session.upstream !== closedClient) {
627	    return;
628	  }
629	  session.upstream = null;
630	  session.pendingServerRequests?.clear();
631	  if (!isWebSocketOpen(downstreamWs)) {
632	    return;
633	  }
634	  if (!session.endpoint || !session.resumeParams?.threadId) {
635	    config.statusTracker?.recordUpstreamError(new Error("upstream closed"), {
636	      subsystem: "live-upstream",
637	    });
638	    downstreamWs.close(1011, "upstream closed");
639	    return;
640	  }
641	  if (session.retryTask) {
642	    return;
643	  }
644	  session.retryTask = recoverSessionUpstream(config, session, downstreamWs, session.generation);
645	}
646	
647	async function recoverSessionUpstream(config, session, downstreamWs, generation) {
648	  const endpoint = session.endpoint;
649	  const resumeParams = session.resumeParams;
650	  let lastError = null;
651	  config.statusTracker?.recordReconnect({
652	    active: true,
653	    attempts: 0,
654	  });
655	
656	  for (let attempt = 1; attempt <= UPSTREAM_RECONNECT_ATTEMPTS; attempt += 1) {
657	    if (session.closing || session.generation !== generation || !isWebSocketOpen(downstreamWs)) {
658	      session.retryTask = null;
659	      config.statusTracker?.recordReconnect({
660	        active: false,
661	        attempts: attempt - 1,
662	      });
663	      return;
664	    }
665	
666	    const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
667	    try {
668	      await initializeClient(client);
669	      const result = await client.request("thread/resume", resumeParams);
670	      assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
671	      if (!isSessionActive(session, downstreamWs, generation)) {
672	        client.close();
673	        session.retryTask = null;
674	        return;
675	      }
676	      // A recovered upstream may have missed live detail events while the
677	      // socket was down, so force the phone through reconnect + rehydrate.
678	      client.close();
679	      session.retryTask = null;
680	      config.statusTracker?.recordReconnect({
681	        active: false,
682	        attempts: attempt,
683	      });
684	      relayLogger(config).info("upstream.recovery_succeeded", {
685	        threadId: resumeParams.threadId,
686	        endpointUrl: endpoint.url,
687	        attempt,
688	      });
689	      downstreamWs.close(1012, "upstream recovered; rehydrate");
690	      return;
691	    } catch (error) {
692	      lastError = error;
693	      config.statusTracker?.recordUpstreamError(error, {
694	        subsystem: "live-upstream",
695	        threadId: resumeParams.threadId,
696	        endpointUrl: endpoint.url,
697	        attempt,
698	      });
699	      client.close();

