1	import Foundation
2	
3	struct DockProjectionOptions: Equatable, Sendable {
4	    let lens: DockLensID
5	    let searchText: String
6	    let filters: DockFilterState
7	
8	    init(
9	        lens: DockLensID = .newest,
10	        searchText: String = "",
11	        filters: DockFilterState = .default
12	    ) {
13	        self.lens = lens
14	        self.searchText = searchText
15	        self.filters = filters
16	    }
17	}
18	
19	struct DockCardProjection: Equatable, Sendable {
20	    let lens: DockLensID
21	    let pinnedRows: [DockRowViewModel]
22	    let allPinnedRows: [DockRowViewModel]
23	    let pinnedSummary: DockPinnedSummary
24	    let rows: [DockRowViewModel]
25	    let groups: [DockProjectionGroupViewModel]
26	    let summary: DockProjectionSummary
27	    let availableFacets: DockProjectionFacets
28	    let emptyReason: DockProjectionEmptyReason?
29	    let isPartial: Bool
30	    let checkingHostCount: Int
31	}
32	
33	extension DockSnapshot {
34	    func project(options: DockProjectionOptions) -> DockCardProjection {
35	        DockCardProjectionProjector(snapshot: self, options: options).project()
36	    }
37	}
38	
39	private struct DockCardProjectionProjector {
40	    let snapshot: DockSnapshot
41	    let options: DockProjectionOptions
42	
43	    func project() -> DockCardProjection {
44	        let searchedRows = snapshot.rows.filter(matchesSearch)
45	        // Idle is a normal status facet. Do not add a second visibility gate.
46	        let filteredRows = searchedRows.filter(matchesFilters)
47	        let pinnedRows = filteredRows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
48	        let bodyRows = filteredRows
49	            .filter { !$0.isPinned }
50	            .sorted(by: rowPrecedesByRelayOrder)
51	        let visibleRows = (pinnedRows + bodyRows).sorted(by: rowPrecedesByRelayOrder)
52	        let allPinnedRows = snapshot.rows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
53	        let groups = groups(for: bodyRows)
54	        let emptyReason = visibleRows.isEmpty ? emptyReason(searchedRows: searchedRows) : nil
55	
56	        return DockCardProjection(
57	            lens: options.lens,
58	            pinnedRows: pinnedRows,
59	            allPinnedRows: allPinnedRows,
60	            pinnedSummary: DockPinnedSummary(
61	                visibleCount: pinnedRows.count,
62	                totalCount: allPinnedRows.count,
63	                hiddenByScopeCount: max(0, allPinnedRows.count - pinnedRows.count)
64	            ),
65	            rows: options.lens == .newest ? bodyRows : [],
66	            groups: groups,
67	            summary: summary(for: visibleRows),
68	            availableFacets: availableFacets(),
69	            emptyReason: emptyReason,
70	            isPartial: snapshot.isPartial,
71	            checkingHostCount: snapshot.hostStates.filter { $0.status == .checking }.count
72	        )
73	    }
74	
75	    private func groups(
76	        for rows: [DockRowViewModel]
77	    ) -> [DockProjectionGroupViewModel] {
78	        switch options.lens {
79	        case .newest:
80	            return []
81	        case .host:
82	            return hostGroups(for: rows)
83	        case .branch:
84	            return branchGroups(for: rows)
85	        }
86	    }
87	
88	    private func hostGroups(
89	        for rows: [DockRowViewModel]
90	    ) -> [DockProjectionGroupViewModel] {
91	        let stateByHost = Dictionary(uniqueKeysWithValues: snapshot.hostStates.map { ($0.host.id, $0) })
92	        return snapshot.hosts.compactMap { host in
93	            if !options.filters.selectedHostIDs.isEmpty,
94	               !options.filters.selectedHostIDs.contains(host.id) {
95	                return nil
96	            }
97	
98	            let hostRows = rows
99	                .filter { rowBelongs($0, to: host.id) }
100	                .sorted(by: rowPrecedesByRelayOrder)
101	            let hostState = stateByHost[host.id]
102	            let isUnavailable = hostState?.status.isUnavailable ?? false
103	            guard !hostRows.isEmpty || isUnavailable || hostState?.status == .checking else {
104	                return nil
105	            }
106	
107	            return DockProjectionGroupViewModel(
108	                id: "host::\(host.id)",
109	                kind: .host,
110	                title: host.displayName,
111	                subtitle: hostState?.status.subtitle ?? "\(hostRows.count) sessions",
112	                rows: hostRows,
113	                hostIDs: [host.id],
114	                displayOrderKey: hostRows.first?.displayOrderKey,
115	                newestActivityDate: hostRows.map(\.lastActivityDate).max(),
116	                runningCount: hostRows.filter { $0.status == .running }.count,
117	                isUnavailable: isUnavailable,
118	                unavailableMessage: hostState?.status.unavailableMessage
119	            )
120	        }
121	        .sorted(by: groupPrecedes)
122	    }
123	
124	    private func branchGroups(
125	        for rows: [DockRowViewModel]
126	    ) -> [DockProjectionGroupViewModel] {
127	        let groupedRows = Dictionary(grouping: rows, by: \.branch)
128	        return groupedRows.map { branch, rows in
129	            let sortedRows = rows.sorted(by: rowPrecedesByRelayOrder)
130	            let hostNames = Set(sortedRows.map(\.hostDisplayName)).sorted()
131	            return DockProjectionGroupViewModel(
132	                id: "branch::\(branch)",
133	                kind: .branch,
134	                title: branch,
135	                subtitle: "\(sortedRows.count) sessions · \(hostNames.joined(separator: ", "))",
136	                rows: sortedRows,
137	                hostIDs: Set(sortedRows.map(hostIDForGroup)).sorted(),
138	                displayOrderKey: sortedRows.first?.displayOrderKey,
139	                newestActivityDate: sortedRows.map(\.lastActivityDate).max(),
140	                runningCount: sortedRows.filter { $0.status == .running }.count,
141	                isUnavailable: false,
142	                unavailableMessage: nil
143	            )
144	        }
145	        .sorted(by: groupPrecedes)
146	    }
147	
148	    private func summary(for rows: [DockRowViewModel]) -> DockProjectionSummary {
149	        var parts: [String] = ["\(rows.count.formatted()) shown"]
150	        parts.append(hostSummaryText)
151	        parts.append(branchSummaryText)
152	        parts.append(statusSummaryText)
153	        parts.append(repositorySummaryText)
154	        parts.append("Source: \(options.filters.source.label)")
155	
156	        let query = normalizedQuery(options.searchText)
157	        if !query.isEmpty {
158	            parts.append("Search: \(query)")
159	        }
160	        if snapshot.isPartial {
161	            parts.append("Partial")
162	        }
163	        parts.append(contentsOf: windowSummaryTexts)
164	
165	        return DockProjectionSummary(
166	            text: parts.joined(separator: " · "),
167	            activeFilterCount: options.filters.activeFilterCount + (query.isEmpty ? 0 : 1),
168	            resultCount: rows.count
169	        )
170	    }
171	
172	    private var hostSummaryText: String {
173	        guard !options.filters.selectedHostIDs.isEmpty else {
174	            return "Hosts: Any"
175	        }
176	        if options.filters.selectedHostIDs.count == 1,
177	           let hostID = options.filters.selectedHostIDs.first {
178	            return "Host: \(hostName(for: hostID))"
179	        }
180	        return "Hosts: \(options.filters.selectedHostIDs.count)"
181	    }
182	
183	    private var branchSummaryText: String {
184	        guard !options.filters.selectedBranches.isEmpty else {
185	            return "Branches: Any"
186	        }
187	        if options.filters.selectedBranches.count == 1,
188	           let branch = options.filters.selectedBranches.first {
189	            return "Branch: \(branch)"
190	        }
191	        return "Branches: \(options.filters.selectedBranches.count)"
192	    }
193	
194	    private var statusSummaryText: String {
195	        let allStatuses = Set(DockRowStatusKind.allCases)
196	        guard options.filters.statusKinds != allStatuses else {
197	            return "Status: Any"
198	        }
199	        if options.filters.statusKinds.count == 1,
200	           let status = options.filters.statusKinds.first {
201	            return "Status: \(status.label)"
202	        }
203	        return "Statuses: \(options.filters.statusKinds.count)"
204	    }
205	
206	    private var repositorySummaryText: String {
207	        let query = normalizedQuery(options.filters.repositoryQuery)
208	        let selectedCount = options.filters.selectedRepositories.count
209	        if selectedCount == 0, query.isEmpty {
210	            return "Repo: Any"
211	        }
212	        if selectedCount == 1,
213	           query.isEmpty,
214	           let repository = options.filters.selectedRepositories.first {
215	            return "Repo: \(repository)"
216	        }
217	        if selectedCount == 0 {
218	            return "Repo search: \(query)"
219	        }
220	        if query.isEmpty {
221	            return "Repos: \(selectedCount)"
222	        }
223	        return "Repos: \(selectedCount), search: \(query)"
224	    }
225	
226	    private var windowSummaryTexts: [String] {
227	        snapshot.hostStates.compactMap { hostState in
228	            guard let window = hostState.status.window else {
229	                return nil
230	            }
231	            return "\(hostState.host.displayName): \(window.message)"
232	        }
233	    }
234	
235	    private func availableFacets() -> DockProjectionFacets {
236	        DockProjectionFacets(
237	            hosts: snapshot.hosts,
238	            branches: uniqueSorted(snapshot.rows.map(\.branch)),
239	            statuses: DockRowStatusKind.allCases.filter { status in
240	                snapshot.rows.contains { $0.status == status }
241	            },
242	            repositories: uniqueSorted(snapshot.rows.map(\.repository)),
243	            sources: DockSourceFilter.allCases.filter { source in
244	                source == .any || snapshot.rows.contains { source.includes($0.origin) }
245	            }
246	        )
247	    }
248	
249	    private func hostName(for hostID: String) -> String {
250	        snapshot.hosts.first { $0.id == hostID }?.displayName ?? hostID
251	    }
252	
253	    private func emptyReason(
254	        searchedRows: [DockRowViewModel]
255	    ) -> DockProjectionEmptyReason {
256	        if snapshot.rows.isEmpty {
257	            return .noData
258	        }
259	        if !normalizedQuery(options.searchText).isEmpty, searchedRows.isEmpty {
260	            return .noSearchMatches
261	        }
262	        if selectedHostsAreUnavailable {
263	            return .hostUnavailable
264	        }
265	        return .noFilterMatches
266	    }
267	
268	    private var selectedHostsAreUnavailable: Bool {
269	        guard !options.filters.selectedHostIDs.isEmpty else {
270	            return false
271	        }
272	        let states = snapshot.hostStates.filter { options.filters.selectedHostIDs.contains($0.host.id) }
273	        return !states.isEmpty && states.allSatisfy(\.status.isUnavailable)
274	    }
275	
276	    private func matchesFilters(_ row: DockRowViewModel) -> Bool {
277	        if !options.filters.selectedHostIDs.isEmpty,
278	           !options.filters.selectedHostIDs.contains(where: { selectedHostID in
279	               rowBelongs(row, to: selectedHostID)
280	           }) {
281	            return false
282	        }
283	        if !options.filters.selectedBranches.isEmpty,
284	           !options.filters.selectedBranches.contains(where: { selected in
285	               row.branch.compare(selected, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
286	           }) {
287	            return false
288	        }
289	        if !options.filters.statusKinds.contains(row.status) {
290	            return false
291	        }
292	        if !options.filters.selectedRepositories.isEmpty,
293	           !options.filters.selectedRepositories.contains(row.repository) {
294	            return false
295	        }
296	        let repositoryQuery = normalizedQuery(options.filters.repositoryQuery)
297	        if !repositoryQuery.isEmpty,
298	           !row.repository.localizedCaseInsensitiveContains(repositoryQuery) {
299	            return false
300	        }
301	        return options.filters.source.includes(row.origin)
302	    }
303	
304	    private func rowBelongs(_ row: DockRowViewModel, to configuredHostID: String) -> Bool {
305	        snapshot.hostIdentityResolver.contains(
306	            rowHostID: row.hostID,
307	            sourceConfiguredHostID: row.sourceHostID,
308	            in: configuredHostID
309	        )
310	            || row.sourceHostID == configuredHostID
311	    }
312	
313	    private func hostIDForGroup(_ row: DockRowViewModel) -> String {
314	        snapshot.hostIdentityResolver.resolve(
315	            rowHostID: row.hostID,
316	            sourceConfiguredHostID: row.sourceHostID
317	        )?.host.id
318	            ?? row.sourceHostID
319	            ?? row.hostID
320	    }
321	
322	    private func matchesSearch(_ row: DockRowViewModel) -> Bool {
323	        let query = normalizedQuery(options.searchText)
324	        guard !query.isEmpty else {
325	            return true
326	        }
327	
328	        return searchableValues(for: row).contains { value in
329	            value.localizedCaseInsensitiveContains(query)
330	        }
331	    }
332	
333	    private func searchableValues(for row: DockRowViewModel) -> [String] {
334	        [
335	            row.title,
336	            row.hostDisplayName,
337	            row.hostID,
338	            row.repository,
339	            row.branch,
340	            row.summary,
341	            row.status.label,
342	            row.label,
343	            row.origin.automationKind,
344	            row.threadID
345	        ].compactMap { $0 }
346	    }
347	
348	    private func groupPrecedes(_ lhs: DockProjectionGroupViewModel, _ rhs: DockProjectionGroupViewModel) -> Bool {
349	        if let lhsOrderKey = lhs.displayOrderKey,
350	           let rhsOrderKey = rhs.displayOrderKey,
351	           lhsOrderKey != rhsOrderKey {
352	            return lhsOrderKey < rhsOrderKey
353	        }
354	        if lhs.displayOrderKey != nil {
355	            return true
356	        }
357	        if rhs.displayOrderKey != nil {
358	            return false
359	        }
360	
361	        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
362	        if titleOrder != .orderedSame {
363	            return titleOrder == .orderedAscending
364	        }
365	        return lhs.id < rhs.id
366	    }
367	
368	    private func rowPrecedesByRelayOrder(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
369	        // Dock rows are relay projection rows. Swift may filter and group them,
370	        // but visual order must remain relay displayOrderKey + projectionID.
371	        if lhs.displayOrderKey == rhs.displayOrderKey {
372	            return stableRowID(lhs) < stableRowID(rhs)
373	        }
374	        return lhs.displayOrderKey < rhs.displayOrderKey
375	    }
376	
377	    private func pinnedRowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
378	        if let lhsOrder = lhs.pinnedOrder,
379	           let rhsOrder = rhs.pinnedOrder,
380	           lhsOrder != rhsOrder {
381	            return lhsOrder < rhsOrder
382	        }
383	        if lhs.pinnedOrder != nil {
384	            return true
385	        }
386	        if rhs.pinnedOrder != nil {
387	            return false
388	        }
389	
390	        let lhsPinnedAt = lhs.pinnedAt ?? Date.distantPast
391	        let rhsPinnedAt = rhs.pinnedAt ?? Date.distantPast
392	        if lhsPinnedAt != rhsPinnedAt {
393	            return lhsPinnedAt < rhsPinnedAt
394	        }
395	
396	        return stableRowID(lhs) < stableRowID(rhs)
397	    }
398	
399	    private func stableRowID(_ row: DockRowViewModel) -> String {
400	        row.id
401	    }
402	
403	    private func normalizedQuery(_ value: String) -> String {
404	        value.trimmingCharacters(in: .whitespacesAndNewlines)
405	    }
406	
407	    private func uniqueSorted(_ values: [String]) -> [String] {
408	        Set(values).sorted { lhs, rhs in
409	            lhs.localizedCaseInsensitiveCompare(rhs) == .orderedAscending
410	        }
411	    }
412	}
