3	public enum JSONValue: Codable, Equatable, Sendable {
4	    case null
5	    case bool(Bool)
6	    case integer(Int64)
7	    case double(Double)
8	    case string(String)
9	    case array([JSONValue])
10	    case object([String: JSONValue])
11	
12	    public init(from decoder: Decoder) throws {
13	        let container = try decoder.singleValueContainer()
14	
15	        if container.decodeNil() {
16	            self = .null
17	        } else if let value = try? container.decode(Bool.self) {
18	            self = .bool(value)
19	        } else if let value = try? container.decode(Int64.self) {
20	            self = .integer(value)
21	        } else if let value = try? container.decode(Double.self) {
22	            self = .double(value)
23	        } else if let value = try? container.decode(String.self) {
24	            self = .string(value)
25	        } else if let value = try? container.decode([JSONValue].self) {
26	            self = .array(value)
27	        } else if let value = try? container.decode([String: JSONValue].self) {
28	            self = .object(value)
29	        } else {
30	            throw DecodingError.dataCorruptedError(
31	                in: container,
32	                debugDescription: "Unsupported JSON value"
33	            )
34	        }
35	    }
36	
37	    public func encode(to encoder: Encoder) throws {
38	        var container = encoder.singleValueContainer()
39	        switch self {
40	        case .null:
41	            try container.encodeNil()
42	        case .bool(let value):
43	            try container.encode(value)
44	        case .integer(let value):
45	            try container.encode(value)
46	        case .double(let value):
47	            guard value.isFinite else {
48	                throw EncodingError.invalidValue(
49	                    value,
50	                    EncodingError.Context(
51	                        codingPath: encoder.codingPath,
52	                        debugDescription: "JSON numbers must be finite"
53	                    )
54	                )
55	            }
56	            try container.encode(value)
57	        case .string(let value):
58	            try container.encode(value)
59	        case .array(let value):
60	            try container.encode(value)
61	        case .object(let value):
62	            try container.encode(value)
63	        }
64	    }
65	
66	    public static func encoded<T: Encodable>(
67	        _ value: T,
68	        encoder: JSONEncoder = JSONEncoder(),
69	        decoder: JSONDecoder = JSONDecoder()
70	    ) throws -> JSONValue {
71	        let data = try encoder.encode(value)
72	        return try decoder.decode(JSONValue.self, from: data)
73	    }
74	
75	    public func decoded<T: Decodable>(
76	        as type: T.Type,
77	        encoder: JSONEncoder = JSONEncoder(),
78	        decoder: JSONDecoder = JSONDecoder()
79	    ) throws -> T {
80	        let data = try encoder.encode(self)
81	        return try decoder.decode(type, from: data)
82	    }
83	}
