211	        switch self {
212	        case .request(let value):
213	            try value.encode(to: encoder)
214	        case .notification(let value):
215	            try value.encode(to: encoder)
216	        case .response(let value):
217	            try value.encode(to: encoder)
218	        case .error(let value):
219	            try value.encode(to: encoder)
220	        }
221	    }
