225	        decoder: JSONDecoder = JSONDecoder()
226	    ) throws -> JSONRPCMessage {
227	        guard let data = text.data(using: .utf8) else {
228	            throw DecodingError.dataCorrupted(
229	                DecodingError.Context(
230	                    codingPath: [],
231	                    debugDescription: "JSON-RPC text is not valid UTF-8"
232	                )
233	            )
234	        }
235	        return try decoder.decode(JSONRPCMessage.self, from: data)
236	    }
237	
238	    public func jsonData(encoder: JSONEncoder = JSONEncoder()) throws -> Data {
239	        try encoder.encode(self)
240	    }
241	
242	    public func jsonString(encoder: JSONEncoder = JSONEncoder()) throws -> String {
243	        let data = try jsonData(encoder: encoder)
244	        guard let text = String(data: data, encoding: .utf8) else {
245	            throw EncodingError.invalidValue(
246	                self,
247	                EncodingError.Context(
248	                    codingPath: [],
249	                    debugDescription: "Encoded JSON-RPC data is not valid UTF-8"
250	                )
251	            )
252	        }
