200	    private func handleStreamUpdate(
201	        _ update: ThreadCardStreamUpdateDTO,
202	        host: DockHostConfiguration,
203	        connection: any ThreadCardStreamConnection
204	    ) async {
205	        guard let delegate else {
206	            return
207	        }
208	
209	        recordStreamActivity(host: host, connection: connection)
210	        let result = await delegate.cardStreamLifecycleApplyUpdate(update, host: host)
211	        if case .needsResync(let reason) = result {
212	            logger.warning("\(self.logName, privacy: .public) stream resync needed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public)")
213	            await resync(host: host, connection: connection)
214	        } else {
215	            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
216	            await delegate.cardStreamLifecyclePublishSnapshot()
217	            let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
218	            logger.info("\(self.logName, privacy: .public) stream update applied view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
219	            let freshness = update.freshness
220	            if freshness.status != .fresh,
221	               rowCount > 0 {
222	                logger.notice("\(self.logName, privacy: .public) stream rows retained view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) freshness=\(freshness.status.rawValue, privacy: .public) rows=\(rowCount, privacy: .public)")
223	            }
224	        }
225	    }
