262	    private func handleStreamFailure(
263	        _ error: Error,
264	        host: DockHostConfiguration,
265	        connection: any ThreadCardStreamConnection
266	    ) async {
267	        guard streamConnections[host.id] != nil else {
268	            return
269	        }
270	        guard let delegate else {
271	            return
272	        }
273	
274	        logger.warning("\(self.logName, privacy: .public) stream update failed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
275	        streamHeartbeatTasks[host.id]?.cancel()
276	        streamHeartbeatTasks[host.id] = nil
277	        streamHeartbeatTokens[host.id] = nil
278	        streamConnections[host.id] = nil
279	        streamTasks[host.id] = nil
280	        await connection.close()
281	        await delegate.cardStreamLifecycleMarkFailure(Self.mapRequestFailure(error), host: host)
282	        await delegate.cardStreamLifecyclePublishSnapshot()
283	        let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
284	        if rowCount > 0 {
285	            logger.notice("\(self.logName, privacy: .public) stream rows retained view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) freshness=offline rows=\(rowCount, privacy: .public)")
286	        }
287	        scheduleReconnect(host: host)
288	    }
