301	    private nonisolated static func mapRequestFailure(_ error: Error) -> DockRequestFailure {
302	        if let failure = error as? DockRequestFailure {
303	            return failure
304	        }
305	        if let clientError = error as? AppServerClientError {
306	            switch clientError {
307	            case .disconnected, .notConnected, .requestTimedOut, .transport:
308	                return .offline(clientError.localizedDescription)
309	            case .duplicateRequestID,
310	                 .malformedMessage,
311	                 .requestCancelled,
312	                 .responseDecoding,
313	                 .server,
314	                 .unexpectedServerRequest,
315	                 .unmatchedResponse:
316	                return .error(clientError.localizedDescription)
317	            }
318	        }
319	        return .error(error.localizedDescription)
320	    }
