343	private final class PCM16Mono24kChunkEmitter: @unchecked Sendable {
344	    private let inputFormat: AVAudioFormat
345	    private let continuation: AsyncStream<VoiceAudioChunk>.Continuation
346	    private let lock = NSLock()
347	    private var nextSequence = 1
348	    private var isClosed = false
349	    private var emittedChunks = 0
350	    private var emittedBytes = 0
351	
352	    init(inputFormat: AVAudioFormat, continuation: AsyncStream<VoiceAudioChunk>.Continuation) {
353	        self.inputFormat = inputFormat
354	        self.continuation = continuation
355	    }
356	
357	    func emit(_ buffer: AVAudioPCMBuffer) {
358	        lock.lock()
359	        guard !isClosed else {
360	            lock.unlock()
361	            return
362	        }
363	        let sequence = nextSequence
364	        nextSequence += 1
365	        lock.unlock()
366	
367	        let audio = pcm16Mono24kData(from: buffer, inputFormat: inputFormat)
368	        guard !audio.isEmpty else {
369	            return
370	        }
371	        lock.lock()
372	        emittedChunks += 1
373	        emittedBytes += audio.count
374	        lock.unlock()
375	        continuation.yield(
376	            VoiceAudioChunk(sequence: sequence, audio: audio, format: .pcm16Mono24k)
377	        )
378	    }
379	
380	    func close() {
381	        lock.lock()
382	        isClosed = true
383	        lock.unlock()
384	    }
385	
386	    var emittedChunkCount: Int {
387	        lock.lock()
388	        defer { lock.unlock() }
389	        return emittedChunks
390	    }
391	
392	    var emittedByteCount: Int {
393	        lock.lock()
394	        defer { lock.unlock() }
395	        return emittedBytes
396	    }
397	
398	    private func pcm16Mono24kData(
399	        from buffer: AVAudioPCMBuffer,
400	        inputFormat: AVAudioFormat
401	    ) -> Data {
402	        let inputFrameCount = Int(buffer.frameLength)
403	        let channelCount = Int(inputFormat.channelCount)
404	        guard inputFrameCount > 0, channelCount > 0, inputFormat.sampleRate > 0 else {
405	            return Data()
406	        }

